; ============================================== u16 perSecond ====

perSecond:
; ---- if ( spent == 0 ) return 0
        mov     ax, [perSecond__spent]
        test    ax, ax
        jne     .L218                       ; unsigned ==
        mov     word [perSecond__ret], 0
