.L218:
; ---- return done / spent * ticksPerSecond + ( done % spent ) * ticksPerSecond / spent
        mov     ax, [perSecond__done]
        mov     bx, [perSecond__spent]
        xor     dx, dx                      ; clear high half for div
        div     bx
        mov     bx, 18
        mul     bx                          ; low 16 bits are sign-agnostic
        push    ax                          ; save lhs: rhs is not a leaf
        mov     ax, [perSecond__done]
        mov     bx, [perSecond__spent]
        xor     dx, dx                      ; clear high half for div
        div     bx
        mov     ax, dx                      ; remainder
        mov     bx, 18
        mul     bx                          ; low 16 bits are sign-agnostic
        mov     bx, [perSecond__spent]
        xor     dx, dx                      ; clear high half for div
        div     bx
        mov     bx, ax
        pop     ax
        add     ax, bx
        mov     [perSecond__ret], ax
        ret

; ============================================== sub report ====

report:
; ---- putStr( label )
        mov     ax, [report__label]
        mov     [putStr__at], ax
        call    putStr
; ---- putNumber( done )
        mov     ax, [report__done]
        mov     [putNumber__n], ax
        call    putNumber
; ---- putStr( addr( sDraws ) )
        mov     ax, sDraws                  ; link-time constant
        mov     [putStr__at], ax
        call    putStr
; ---- putNumber( spent )
        mov     ax, [report__spent]
        mov     [putNumber__n], ax
        call    putNumber
; ---- putStr( addr( sTicks ) )
        mov     ax, sTicks                  ; link-time constant
        mov     [putStr__at], ax
        call    putStr
; ---- putNumber( perSecond( done, spent ) )
        mov     ax, [report__done]
        mov     [perSecond__done], ax
        mov     ax, [report__spent]
        mov     [perSecond__spent], ax
        call    perSecond
        mov     ax, [perSecond__ret]
        mov     [putNumber__n], ax
        call    putNumber
; ---- putStr( addr( sRate ) )
        mov     ax, sRate                   ; link-time constant
        mov     [putStr__at], ax
        call    putStr
; ---- newline()
        call    newline
        ret

; ==================================================== int helpers ====
; One per distinct interrupt: the literal is baked in, so the register
; sync is emitted once rather than at every call site.

int10:
        push    es
        mov     ax, [_ax]
        mov     bx, [_bx]
        mov     cx, [_cx]
        mov     dx, [_dx]
        mov     si, [_si]
        mov     di, [_di]
        int     0x10
        mov     [_ax], ax
        mov     [_bx], bx
        mov     [_cx], cx
        mov     [_dx], dx
        mov     [_si], si
        mov     [_di], di
        pop     es
        ret

int21:
        push    es
        mov     ax, [_ax]
        mov     bx, [_bx]
        mov     cx, [_cx]
        mov     dx, [_dx]
        mov     si, [_si]
        mov     di, [_di]
        int     0x21
        mov     [_ax], ax
        mov     [_bx], bx
        mov     [_cx], cx
        mov     [_dx], dx
        mov     [_si], si
        mov     [_di], di
        pop     es
        ret

